//! The generated server's transport-free entry point (story `transport-free-entry-point`).
//!
//! A conformance runner or an in-process caller drives the system by qualified name, with no
//! socket and no hand-kept dispatch table. The harness below lives outside the generated bytes: it
//! depends on the synthesised crates by path, drives every command and view the fixture's
//! surface declares through `handle`, and holds each answer against the one the HTTP dispatcher
//! gives for the same input — so "the same decoding, refusals and encoding" is observed, not
//! assumed. Nothing binds a socket: the dispatcher is called with a request value.

use std::path::{Path, PathBuf};
use std::process::{Command, Output};

use ess_compiler::{resolve::compile, source::SourceMap, EssIr};
use ess_domain::{spec::RawSpecFile, system::Source, Specification};
use ess_gen::http::{self, Served};
use ess_synth::{synthesize_for, Synthesis, Target};

/// Two commands and two views on one served surface. Each command keeps an `external` outcome,
/// so it stays an obligation the harness satisfies whatever synthesis can generate.
const MODEL: &str = "format: ess/15
system: desk
version: v1
domain: desk.tickets
entities:
  - name: desk.tickets.Ticket
    identity: {name: id, type: String}
    fields:
      - {name: title, type: String}
    lifecycle:
      initial: Open
      states: [Open]
      terminal: [Open]
events:
  - name: desk.tickets.Opened
    fields:
      - {name: id, type: String}
      - {name: title, type: String}
  - name: desk.tickets.Ponged
    fields:
      - {name: note, type: String}
commands:
  - name: desk.tickets.OpenTicket
    input:
      - {name: id, type: String}
      - {name: title, type: String}
    outcomes:
      - name: opened
        emits: [desk.tickets.Opened]
        payload:
          desk.tickets.Opened: {id: input.id, title: input.title}
      - name: duplicate
        external: a ticket with this id is already open
        error: desk.tickets.Duplicate
  - name: desk.tickets.Ping
    input:
      - {name: note, type: String}
    outcomes:
      - name: ponged
        emits: [desk.tickets.Ponged]
        payload:
          desk.tickets.Ponged: {note: input.note}
      - name: busy
        external: the desk is not answering
        error: desk.tickets.Busy
errors:
  - name: desk.tickets.Duplicate
    fields:
      - {name: id, type: String}
  - name: desk.tickets.Busy
views:
  - name: desk.tickets.Tickets
    source: desk.tickets.Ticket
    consistency: eventual
    fields:
      - {name: id, type: String}
      - {name: title, type: String}
  - name: desk.tickets.Titles
    source: desk.tickets.Ticket
    consistency: eventual
    fields:
      - {name: title, type: String}
components:
  - component: desk-service
    owns: {domains: [desk.tickets]}
    accepts: {commands: [desk.tickets.OpenTicket, desk.tickets.Ping]}
    publishes: {events: [desk.tickets.Opened, desk.tickets.Ponged]}
    reached_by: network
";

/// The harness: a realization of the fixture's obligations, then every construct through
/// `handle` and through the HTTP dispatcher, answer for answer. Its argument list is the route
/// table the test derives from the model, `name method path` per construct, so a construct the
/// harness forgot to drive fails here rather than passing unobserved.
const HARNESS: &str = r##"use std::collections::BTreeSet;

use desk_server::desk_service as surface;
use desk_server::{entry, http, json};
use desk_types::obligation::UnmetObligation;
use desk_types::tickets::{self as t, obligations as o};

struct Desk;

impl o::OpenTicketBehavior for Desk {
    fn open_ticket(&mut self, input: t::OpenTicket) -> Result<t::OpenTicketOutcome, UnmetObligation> {
        if input.title == "again" {
            return Ok(t::OpenTicketOutcome::Duplicate {
                error: t::Duplicate { id: input.id },
            });
        }
        Ok(t::OpenTicketOutcome::Opened {
            opened: t::Opened {
                id: input.id,
                title: input.title,
            },
        })
    }
}

impl o::PingBehavior for Desk {
    fn ping(&mut self, input: t::Ping) -> Result<t::PingOutcome, UnmetObligation> {
        if input.note == "busy" {
            return Ok(t::PingOutcome::Busy { error: t::Busy {} });
        }
        Err(UnmetObligation {
            capability: "command_behavior",
            source: "desk.tickets.Ping",
        })
    }
}

impl o::TicketsQuery for Desk {
    fn tickets(&self) -> Result<Vec<t::Tickets>, UnmetObligation> {
        Ok(vec![t::Tickets {
            id: "t1".to_owned(),
            title: "printer".to_owned(),
        }])
    }
}

impl o::TitlesQuery for Desk {
    fn titles(&self) -> Result<Vec<t::Titles>, UnmetObligation> {
        Err(UnmetObligation {
            capability: "view_query",
            source: "desk.tickets.Titles",
        })
    }
}

/// `(name, input)`: a declared branch, a declared error with its payload, one without, an input
/// the schema refuses, input that is not an object, an unmet command obligation, a view's rows
/// and an unmet view obligation.
const CASES: &[(&str, &str)] = &[
    ("desk.tickets.OpenTicket", r#"{"id":"t1","title":"printer"}"#),
    ("desk.tickets.OpenTicket", r#"{"id":"t1","title":"again"}"#),
    ("desk.tickets.OpenTicket", r#"{"id":"t1"}"#),
    ("desk.tickets.OpenTicket", r#"[1]"#),
    ("desk.tickets.Ping", r#"{"note":"busy"}"#),
    ("desk.tickets.Ping", r#"{"note":"hi"}"#),
    ("desk.tickets.Tickets", "null"),
    ("desk.tickets.Titles", "null"),
];

fn main() {
    let arguments: Vec<String> = std::env::args().skip(1).collect();
    let routes: Vec<(&str, &str, &str)> = arguments
        .chunks(3)
        .map(|row| (row[0].as_str(), row[1].as_str(), row[2].as_str()))
        .collect();
    assert!(!routes.is_empty(), "the test passes the route table");

    let mut system = desk_system::System::new(desk_service::DeskService::new(Desk));
    let mut driven = BTreeSet::new();
    for (name, input) in CASES {
        let (_, method, path) = routes
            .iter()
            .find(|(declared, _, _)| declared == name)
            .unwrap_or_else(|| panic!("`{name}` is a route the model declares"));
        driven.insert(*name);

        let value = json::parse(input).expect("the case's input parses");
        let handled = surface::handle(&mut system, name, value);
        let body = if *method == "GET" { Vec::new() } else { input.as_bytes().to_vec() };
        let request = http::Request {
            method: (*method).to_owned(),
            path: (*path).to_owned(),
            headers: vec![("authorization".to_owned(), "Bearer entry".to_owned())],
            body,
        };
        let answered = surface::dispatch(&mut system, &request);
        match &handled {
            Ok(value) => {
                let served = json::parse(&answered.body).expect("the served body parses");
                assert_eq!(&served, value, "`{name}` answers the same outcome on both paths");
            }
            Err(refused) => {
                assert_eq!(
                    answered,
                    http::Response::refusal(refused.status(), &refused.to_string()),
                    "`{name}` refuses the same way on both paths"
                );
            }
        }
        let verdict = if handled.is_ok() { "ok" } else { "refused" };
        println!("{name} {verdict} {} {}", answered.status, answered.body);
    }
    let declared: BTreeSet<&str> = routes.iter().map(|(name, _, _)| *name).collect();
    assert_eq!(driven, declared, "every command and view the surface declares is driven");

    let unknown = surface::handle(&mut system, "desk.tickets.Nowhere", json::Value::Null);
    assert_eq!(
        unknown,
        Err(entry::Refused::Unknown("desk.tickets.Nowhere".to_owned()))
    );
    let refused = unknown.unwrap_err();
    let error: &dyn std::error::Error = &refused;
    println!("unknown {}", error);
}
"##;

fn ir(source: &str) -> EssIr {
    let spec = Specification::assemble([(
        Source::new("spec.yaml"),
        RawSpecFile::parse(source).expect("well formed"),
    )])
    .unwrap_or_else(|errors| panic!("validates: {errors}"));
    let mut sources = SourceMap::new();
    sources.insert("spec.yaml", source);
    compile(&spec, &sources).unwrap_or_else(|errors| panic!("compiles: {errors}"))
}

fn scratch(label: &str) -> PathBuf {
    Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("transport-free-entry-{label}"))
}

fn write(synthesis: &Synthesis, directory: &Path) {
    let _ = std::fs::remove_dir_all(directory);
    for (relative, artifact) in &synthesis.artifacts {
        let destination = directory.join(relative);
        std::fs::create_dir_all(destination.parent().unwrap()).unwrap();
        std::fs::write(&destination, &artifact.contents).unwrap();
    }
}

/// Cargo inside the harness, with every warning an error: generated code that warns is an emitter
/// defect a consumer's own `-D warnings` build would inherit.
fn cargo(directory: &Path, arguments: &[String]) -> Output {
    let output = Command::new(std::env::var_os("CARGO").expect("Cargo supplies its executable"))
        .args(arguments)
        .current_dir(directory)
        .env_remove("CARGO_TARGET_DIR")
        .env_remove("CARGO_ENCODED_RUSTFLAGS")
        .env("RUSTFLAGS", "-D warnings")
        .output()
        .expect("cargo runs");
    eprintln!(
        "cargo {arguments:?} in {}\n{}{}",
        directory.display(),
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    output
}

#[test]
fn every_command_and_view_is_driven_by_name_without_a_socket() {
    let ir = ir(MODEL);
    let synthesis = synthesize_for(&ir, Target::Rust).expect("the fixture synthesizes");
    let component = ir
        .components()
        .values()
        .next()
        .expect("the fixture has a component");
    let mut table = Vec::new();
    for route in http::routes(&ir, component) {
        let name = match route.serves {
            Served::Command(handle) => ir.command(handle).name.to_string(),
            Served::View(handle) => ir.view(handle).name.to_string(),
        };
        table.extend([name, route.method.as_str().to_owned(), route.path]);
    }
    assert_eq!(table.len(), 12, "two commands and two views: {table:?}");

    let root = scratch("harness");
    let generated = root.join("generated");
    write(&synthesis, &generated);
    let harness = root.join("harness");
    std::fs::create_dir_all(harness.join("src")).unwrap();
    std::fs::write(
        harness.join("Cargo.toml"),
        "[package]\nname = \"entry-harness\"\nversion = \"0.0.0\"\nedition = \"2021\"\n\n\
         [dependencies]\ndesk-server = { path = \"../generated/crates/desk-server\" }\n\
         desk-system = { path = \"../generated/crates/desk-system\" }\n\
         desk-service = { path = \"../generated/crates/desk-service\" }\n\
         desk-types = { path = \"../generated/crates/desk-types\" }\n\n[workspace]\n",
    )
    .unwrap();
    std::fs::write(harness.join("src/main.rs"), HARNESS).unwrap();
    let target = root.join("target");
    let mut arguments: Vec<String> = [
        "run",
        "--offline",
        "--quiet",
        "--target-dir",
        target.to_str().unwrap(),
        "--",
    ]
    .iter()
    .map(|argument| (*argument).to_owned())
    .collect();
    arguments.extend(table);
    let run = cargo(&harness, &arguments);
    let stdout = String::from_utf8_lossy(&run.stdout).into_owned();
    let _ = std::fs::remove_dir_all(&root);
    assert!(
        run.status.success(),
        "the harness drives the generated entry point"
    );
    assert_eq!(stdout, EXPECTED);
}

/// What the harness prints: each case's verdict, the HTTP status the same input is served with,
/// and the served body; then the unknown name, as the typed error renders it.
const EXPECTED: &str = concat!(
    "desk.tickets.OpenTicket ok 202 {\"outcome\":\"opened\",\"published\":[{\"event\":\
     \"desk.tickets.Opened\",\"payload\":{\"id\":\"t1\",\"title\":\"printer\"}}]}\n",
    "desk.tickets.OpenTicket ok 502 {\"outcome\":\"duplicate\",\"published\":[],\"error\":\"desk.tickets.Duplicate\",\
     \"payload\":{\"id\":\"t1\"}}\n",
    "desk.tickets.OpenTicket refused 400 {\"refused\":\"body.title: expected a value, found \
     nothing\"}\n",
    "desk.tickets.OpenTicket refused 400 {\"refused\":\"body: expected an object, found an \
     array\"}\n",
    "desk.tickets.Ping ok 502 {\"outcome\":\"busy\",\"published\":[],\"error\":\"desk.tickets.Busy\"}\n",
    "desk.tickets.Ping refused 501 {\"refused\":\"unmet obligation: command_behavior \
     `desk.tickets.Ping` — see PLAN.md\"}\n",
    "desk.tickets.Tickets ok 200 {\"rows\":[{\"id\":\"t1\",\"title\":\"printer\"}]}\n",
    "desk.tickets.Titles refused 501 {\"refused\":\"unmet obligation: view_query \
     `desk.tickets.Titles` — see PLAN.md\"}\n",
    "unknown `desk.tickets.Nowhere` is not a command or view this surface declares\n",
);
